using System;using System.IO;using System.Collections.Generic;using System.Web.Script.Serialization;
internal static class ProbeJsonRegression {
    internal static int Main(string[] args){var reference=new JavaScriptSerializer();var writer=new LpacProbeJson();int checks=0;foreach(var file in args)foreach(var line in File.ReadAllLines(file))if(line.StartsWith("SFUNC_NATIVE:")||line.StartsWith("SFNATIVE_REPORT:")){int colon=line.IndexOf(':');var original=reference.DeserializeObject(line.Substring(colon+1));string serialized=writer.Serialize(original);if(reference.Serialize(reference.DeserializeObject(serialized))!=reference.Serialize(original))throw new Exception("RAW_REPORT_ROUNDTRIP");checks++;}string sample="中文\\\"\n\r\t\0";var parsed=reference.Deserialize<Dictionary<string,object>>(writer.Serialize(new{text=sample,zero=0,maximum=UInt32.MaxValue,negative=-2147024891,missing=(string)null,flag=true}));if((string)parsed["text"]!=sample||Convert.ToUInt64(parsed["maximum"])!=UInt32.MaxValue||Convert.ToInt32(parsed["negative"])!=-2147024891||parsed["missing"]!=null||!(bool)parsed["flag"])throw new Exception("PRIMITIVES");checks++;if(checks<5)throw new Exception("RAW_COVERAGE");Console.WriteLine("{\"raw_and_primitive_roundtrips\":"+checks+",\"inner_exit_code\":0}");return 0;}
}
